// Filter posts due to publish now
const now = new Date();
const currentTime = now.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' });
const currentDate = now.toISOString().split('T')[0];

const allPosts = $input.all().map(item => item.json);

const toPublish = allPosts.filter(post => {
  if (post.status !== 'scheduled' && post.status !== 'ready') return false;
  if (post.date !== currentDate) return false;

  const postTime = post.time || '00:00';
  const [postHour, postMinute] = postTime.split(':').map(Number);
  const [currentHour, currentMinute] = currentTime.split(':').map(Number);

  const diffMinutes = (currentHour - postHour) * 60 + (currentMinute - postMinute);
  return diffMinutes >= 0 && diffMinutes < 60; // Within the hour
});

console.log(`Found ${toPublish.length} posts to publish`);

return toPublish.map(post => ({
  json: {
    ...post,
    platforms: post.platform?.split(',').map(p => p.trim().toLowerCase()) || ['twitter'],
    timestamp: now.toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}));

// Format content for Twitter
const post = $input.first().json;

const content = post.content || '';
const hashtags = post.hashtags ? `\n\n${post.hashtags}` : '';
const link = post.link ? `\n\n${post.link}` : '';

// Twitter: max 280 chars
let tweet = content + hashtags + link;
if (tweet.length > 280) {
  tweet = content.substring(0, 250) + '...' + hashtags + link;
  if (tweet.length > 280) {
    tweet = tweet.substring(0, 277) + '...';
  }
}

return [{
  json: {
    ...post,
    platform: 'twitter',
    formatted_content: tweet,
    platform_config: {
      max_length: 280,
      supports_images: true,
      supports_links: true
    }
  }
}];

